export const money=v=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(v);
export const lineKey=l=>l.id+'|'+l.variantId;
export function normalizeBag(raw,products){if(!Array.isArray(raw))return [];const result=new Map();for(const l of raw.slice(0,100)){if(!l||typeof l!=='object')continue;const p=products.find(p=>p.id===l.id),v=p?.variants.find(v=>v.id===l.variantId);if(!v||!Number.isInteger(l.qty)||l.qty<1)continue;const key=lineKey(l);result.set(key,{id:p.id,variantId:v.id,qty:Math.min(99,(result.get(key)?.qty||0)+l.qty)})}return [...result.values()]}
export const bagTotal=(lines,products)=>lines.reduce((sum,l)=>sum+Math.round((products.find(p=>p.id===l.id)?.variants.find(v=>v.id===l.variantId)?.price||0)*100)*l.qty,0)/100;
export function filterProducts(products,{search='',category='All products',savedOnly=false,saved=[],sort='featured'}={}){let out=products.filter(p=>(category==='All products'||p.category===category)&&(!savedOnly||saved.includes(p.id))&&`${p.name} ${p.category} ${p.brand}`.toLowerCase().includes(search.trim().toLowerCase()));if(sort==='price-low')out.sort((a,b)=>a.price-b.price);if(sort==='price-high')out.sort((a,b)=>b.price-a.price);if(sort==='name')out.sort((a,b)=>a.name.localeCompare(b.name));return out}
